const GOATCOUNTER_CODE = "m4qfb47n5g";

const endpoint = "https://" + GOATCOUNTER_CODE + ".goatcounter.com";

const tracker = document.createElement("script");
tracker.async = true;
tracker.src = "https://gc.zgo.at/count.js";
tracker.dataset.goatcounter = endpoint + "/count";
document.body.appendChild(tracker);

const target = document.getElementById("visitor-count");
if (target) {
    fetch(endpoint + "/counter/TOTAL.json", { cache: "no-cache" })
        .then(function (res) {
            if (!res.ok) throw new Error("Counter unavailable (" + res.status + ")");
            return res.json();
        })
        .then(function (data) {
            if (!(parseInt(String(data.count).replace(/\D/g, ""), 10) > 0)) throw new Error("No visits yet");
            target.textContent = data.count;
        })
        .catch(function () {
            if (target.parentElement) target.parentElement.hidden = true;
        });
}
